package com.galandras12.droidbeep

import com.galandras12.droidbeep.core.Crypto
import com.galandras12.droidbeep.core.Ecdh163
import com.galandras12.droidbeep.core.EcdhKeys
import com.galandras12.droidbeep.core.Sha3
import com.galandras12.droidbeep.core.toHex
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test

/**
 * Test vectors generated by the real BeeBEEP sources (src/ecdh/ECDH.cpp, src/core/Rijndael.cpp and
 * the Protocol::encryptByteArray code path) compiled against Qt 5.15.
 */
class CryptoVectorsTest {
    private fun hex(s: String): ByteArray = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    private val privA = hex("030a11181f262d343b424950575e656c737a81888f969da4")
    private val privB = hex("fff4e9ded3c8bdb2a79c91867b70655a4f44392e23180d02")
    private val pubA = "177:179:253:68:92:188:31:142:119:14:180:81:177:21:25:194:49:109:49:69:5:0:0:0:18:211:149:4:231:104:95:171:211:213:168:126:58:228:171:189:41:169:186:172:4:0:0:0"
    private val pubB = "19:194:162:153:194:32:35:172:119:6:47:216:157:138:255:108:47:165:22:27:0:0:0:0:127:229:107:9:32:201:78:193:71:242:159:175:90:52:248:240:11:57:169:210:6:0:0:0"
    private val sharedText = "MTMzMTg0ODg0MjQxMjYyNzEwNDIxODI0NTEwMjQyMTk2MzA1OTEzMzE1NDcxMTY2MjAyNDAwMDE4MzUxMzMxMzQ5MzExMjAyNDgxODkwNzcxMzQ1NTMxMTYxOTY5MDQ1MTM4MTQ4MzAwMA"
    private val plain = hex("4245452d43484154e280a931323334e280a935e280a930e280a9e280a9323032362d31302d31325431303a30303a30305ae280a968656c6c6f20202020202020")

    @Test
    fun publicKeysMatchTheCppImplementation() {
        assertEquals(pubA, Ecdh163.publicKeyToString(Ecdh163.publicKeyBytes(privA)))
        assertEquals(pubB, Ecdh163.publicKeyToString(Ecdh163.publicKeyBytes(privB)))
    }

    @Test
    fun sharedKeyMatchesAndIsSymmetric() {
        val a = Ecdh163.sharedPoint(privA, Ecdh163.publicKeyFromString(pubB)!!)
        val b = Ecdh163.sharedPoint(privB, Ecdh163.publicKeyFromString(pubA)!!)
        assertNotNull(a)
        assertArrayEquals(a, b)
        assertEquals(sharedText, String(Ecdh163.sharedKeyText(a!!), Charsets.ISO_8859_1))
    }

    @Test
    fun randomKeysAgree() {
        repeat(3) {
            val k1 = EcdhKeys()
            val k2 = EcdhKeys()
            val s1 = k1.generateSharedKey(k2.publicKey)
            val s2 = k2.generateSharedKey(k1.publicKey)
            assertNotNull(s1)
            assertArrayEquals(s1, s2)
        }
    }

    @Test
    fun invalidPublicKeyIsRejected() {
        val bad = ByteArray(48) { 7 }
        assertEquals(null, Ecdh163.sharedPoint(privA, bad))
    }

    @Test
    fun cipherKeys() {
        assertEquals("415db335238c6070bd9d3717d905a0eb83aa5d31", String(Crypto.createCipherKey(sharedText.toByteArray(), 12)))
        assertEquals("66cb8a14cfc15def3ecc41f94d3f3fd8baf40c90a69f02ec217de01a348b63c1", String(Crypto.createCipherKey(sharedText.toByteArray(), 19)))
    }

    @Test
    fun aesBlocksMatch() {
        val k12 = Crypto.createCipherKey(sharedText.toByteArray(), 12)
        val k13 = Crypto.createCipherKey(sharedText.toByteArray(), 19)
        assertEquals("ab4b5182625b8fc9ca2db5b0f688920b1201e7cfd71770f70467f7f4076428635eb415aebfc3a642328570862560985342a365a5a690a3cba9e151b7ca3e229c", Crypto.encrypt(plain, k12, 96).toHex())
        assertEquals("68bdb169394bf46c3030de3e5b10dcc720f3c2f865ea9beb8fd22d7fd67881c363ebb5771fba1121bd94ace8ce847ec118dd4357ae46c65083da0a181a0d1335", Crypto.encrypt(plain, k13, 96).toHex())
        assertArrayEquals(plain, Crypto.decrypt(Crypto.encrypt(plain, k12, 96), k12, 96))
    }

    @Test
    fun helloUsesAllZeroKeyAtProtocolOne() {
        val pwd = Crypto.passwordHash("")
        assertEquals("f60789c91a817da7c89d15414a72871f46fd557b", String(pwd))
        assertEquals("346c0a87ce8d22a1e4063b7a13e1e17f4f10cb5de58bb160442c9839fe9542ef3f52b2362ba2c5d8c10cbdebb0e4c4c1982d9ac9b638914268018f895024a73e", Crypto.encrypt(plain, pwd, 1).toHex())
    }

    @Test
    fun authHash() {
        assertEquals("f03af7491db7c6428ee77e7cb33fd39a08617032", Crypto.hash("Andris", Crypto.passwordHash("*")))
    }

    @Test
    fun sha3MatchesJdk() {
        val md = java.security.MessageDigest.getInstance("SHA3-256")
        for (len in listOf(0, 1, 55, 135, 136, 137, 300)) {
            val data = ByteArray(len) { (it * 31 + 7).toByte() }
            assertArrayEquals("len=$len", md.digest(data), Sha3.sha3_256(data))
        }
    }
}
